--region handler
function DreamAdventuresStoreCell:OnClickHandler()
    local currencyInfo = table.takeFirst(self._productDojo.prices)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = self._productDojo.goodsId,
        prices         = self._productDojo.prices,
        maxBuyNum      = self._productDojo.currentStock,
        rewards        = self._productDojo.rewards,
        isShowNum = true,
        isBackDialog = true,
        buyCb = function (price, buyNum)
            local youOwn = GoodsUtils.GetThingNo(currencyInfo.currency)
            if youOwn < currencyInfo.current then
                GameUtils.Toast(localize("货币不足"))
                return
            end

            local requestData = {
                productId = self._productDojo.productId,
                num = buyNum,
                currency = currencyInfo.currency,
                activityUuid = self._activityDojo.id,
                activityType = self._activityDojo.type
            }
            GameUtils.Request(Interfaces.OverseaMidFestivalShopBuy, requestData, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    return
                end
                local jsonData = response.data
                local rewards = jsonData.rewards
                if #rewards > 0 then
                    GoodsUtils.DrawRewards(rewards)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                end

                -- 扣除货币
                GoodsUtils.DrawRewards({
                    {
                        goodsId = currencyInfo.currency,
                        num = -currencyInfo.current * checkInt(buyNum)
                    }
                })

                --local mallDojo = self._activityComp:GetMallDojo()
                --mallDojo:DecreaseCurrentStock()
                Events.Broadcast(Constants.EventNames.DreamAdventuresStoreBuy)
            end)
        end
    }}, {
        --{ id = Constants.UITypeIds.UIActivityMidFestivalShopDialog }
    })
end
--endregion handler

--region public
---@param product MidFestivalProductDojo
function DreamAdventuresStoreCell:Refresh(product)
    self._activityDojo = DreamAdventuresMgr:GetActivityDojo()
    self._productDojo = product
    self._goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(product.icon)
    self:RefreshUI()
end
--endregion public

--region private
function DreamAdventuresStoreCell:RefreshUI()
    if isNull(self._productDojo) or isNull(self._goodsVo) then
        return
    end

    -- 基本信息
    local roleGoods = self.BtnNode:Find("RoleGoods")
    if GoodsUtils.IsCardType(self._goodsVo.id) then
        local imageRoleIcon = roleGoods.transform:Find("ImgRoleIcon")
        local imgOccupation = roleGoods.transform:Find("ImgOccupation")
        CfUtils.SetActive(roleGoods, true)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.FillImage(imageRoleIcon, self._goodsVo.photoPath)
        CfUtils.SetActive(imgOccupation, self._goodsVo.type == Constants.IDType.CardSkin)
    else
        CfUtils.SetActive(roleGoods, false)
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.FillImage(self.ImgIcon, self._goodsVo.photoPath)
    end

    CfUtils.FillText(self.TextName, string.format("%s x%d",self._goodsVo.name, self._productDojo.num))

    -- 价格
    local priceInfo = self._productDojo.prices[1]
    local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(priceInfo.currency)
    CfUtils.FillText(self.Price1.transform:Find("TextNumber"), priceInfo.current)
    CfUtils.FillImage(self.Price1.transform:Find("ImgIcon"), currencyVo.photoPath)
    CfUtils.SetActive(self.Price1.transform:Find("ImgIcon"), true)
    if checkNumber(priceInfo.original) > 0 then
        CfUtils.FillText(self.Price2.transform:Find("TextNumber"), priceInfo.original)
        CfUtils.FillImage(self.Price2.transform:Find("ImgIcon"), currencyVo.photoPath)
        CfUtils.SetActive(self.Price2.transform:Find("ImgIcon"), true)
    else
        CfUtils.SetActive(self.Price2, false)
    end

    -- 库存
    local isEnough = (self._productDojo.currentStock == -1) or (self._productDojo.currentStock > 0)
    --CfUtils.SetActive(self.DisableBg, not isEnough)
    --CfUtils.SetActive(self.Lock, not isEnough)
    CfUtils.SetActive(self.SellOutGroup, not isEnough)
    CfUtils.SetActive(self.DisableBg, not isEnough)
    CfUtils.FillText(self.TextNumber2, self._productDojo.currentStock == -1 and "∞" or self._productDojo.currentStock)

    -- 折扣角标
    local tabType = checkInt(self._productDojo.iconId)
    if tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(self._productDojo.iconTitle) * 100))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
    elseif tabType == TagType.Recommend then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
    elseif tabType == TagType.All then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(self._productDojo.iconTitle) * 100))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
    end

    -- 活动时间
    CfUtils.SetActive(self.TimerGroup, false)

    -- 商品星级
    local starCount = checkNumber(self._goodsVo.quality)
    for i = 1, starCount do
        local starGo = self.Star.transform:Find("ImgStar"..i)
        if isNotNull(starGo) then
            CfUtils.SetActive(starGo, true)
        end
    end
    CfUtils.SetUISwitchImage(self.GoodQuality, starCount)
end
--endregion private

return DreamAdventuresStoreCell